# All infrastructure for payables-service. Changes go through terraform plan in CI.

resource "aws_db_instance" "payables" {
  identifier              = "payables-prod"
  engine                  = "postgres"
  engine_version          = "16.4"
  instance_class          = "db.m6g.large"
  allocated_storage       = 100 # GB
  backup_retention_period = 14
}

resource "aws_s3_bucket" "artifacts" {
  bucket = "acme-payables-artifacts"
}

resource "aws_s3_bucket_lifecycle_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  rule {
    id     = "expire-build-artifacts"
    status = "Enabled"
    filter {}
    expiration {
      days = 90
    }
  }
}

resource "aws_ecs_service" "api" {
  name          = "payables-api"
  desired_count = 2
  launch_type   = "FARGATE"
  # Fargate task storage is ephemeral: it is not shared between tasks
  # and is discarded when a task is replaced during a deploy.
}

-- 0042: ledger entries for the new billing ledger.
-- The key type of ledger_entries.id is under review; this draft follows
-- the convention of every other billing table (bigint identity).

CREATE TABLE ledger_entries (
    id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    account_id    bigint      NOT NULL REFERENCES accounts (id),
    entry_type    text        NOT NULL CHECK (entry_type IN ('charge', 'credit', 'refund', 'fee')),
    amount_minor  bigint      NOT NULL,
    currency      char(3)     NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX ledger_entries_account_created ON ledger_entries (account_id, created_at);

CREATE TABLE ledger_allocations (
    id               bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    debit_entry_id   bigint NOT NULL REFERENCES ledger_entries (id),
    credit_entry_id  bigint NOT NULL REFERENCES ledger_entries (id),
    amount_minor     bigint NOT NULL
);

CREATE INDEX ledger_allocations_debit ON ledger_allocations (debit_entry_id);
CREATE INDEX ledger_allocations_credit ON ledger_allocations (credit_entry_id);

import { Router } from "express";
import { getOrder } from "../../services/orders";

export const ordersRouter = Router();

// GET /orders/:id
// Response today: { id, status, total, currency, items[] }
// total is a decimal number in major units (e.g. 19.99). ADR 004 says money
// must be integer minor units, and changing the type of total breaks every
// client that parses it as a float.
ordersRouter.get("/orders/:id", async (req, res) => {
  const order = await getOrder(req.params.id);
  if (!order) {
    return res.status(404).type("application/problem+json").send({
      type: "https://api.example.com/problems/not-found",
      title: "Order not found",
      status: 404,
    });
  }
  res.json({
    id: order.id,
    status: order.status,
    total: order.totalMinor / 100,
    currency: order.currency,
    items: order.items.map((i) => ({ sku: i.sku, quantity: i.quantity, price: i.priceMinor / 100 })),
  });
});

