/** @type {import('jest').Config} */
export default {
  preset: "ts-jest/presets/default-esm",
  testEnvironment: "node",
  extensionsToTreatAsEsm: [".ts"],
  moduleNameMapper: {
    // Sources import siblings with a .js suffix (ESM); point Jest at the .ts file.
    "^(\\.{1,2}/.*)\\.js$": "$1",
  },
  transform: {
    "^.+\\.ts$": ["ts-jest", { useESM: true }],
  },
  // node-fetch 3 and nanoid 5 are ESM-only, so Jest has to transform them.
  // This pattern is why a cold CI run spends about 40 s in transforms.
  transformIgnorePatterns: ["/node_modules/(?!(node-fetch|nanoid)/)"],
  coverageProvider: "v8",
  testTimeout: 15000,
};

"""flake8 plugin: structured-logging rules for data-platform services."""

import ast

LOG_METHODS = {"debug", "info", "warning", "error", "exception", "critical"}


class AcmeLoggingChecker:
    name = "flake8-acme-logging"
    version = "1.4.0"

    def __init__(self, tree: ast.AST) -> None:
        self.tree = tree

    def run(self):
        for node in ast.walk(self.tree):
            if not isinstance(node, ast.Call) or not isinstance(node.func, ast.Attribute):
                continue
            func = node.func
            if func.attr == "getLogger" and getattr(func.value, "id", None) == "logging":
                yield node.lineno, node.col_offset, "ACM001 use structlog.get_logger()", type(self)
            if func.attr in LOG_METHODS and node.args:
                first = node.args[0]
                if isinstance(first, ast.JoinedStr):
                    yield node.lineno, node.col_offset, "ACM002 f-string in log call", type(self)
                if isinstance(first, ast.BinOp) and isinstance(first.op, ast.Mod):
                    yield node.lineno, node.col_offset, "ACM002 %-format in log call", type(self)
